export const READ_SYNC_ROLES=['guest','floor','kitchen','owner'];
export function createReadSyncDemo(){let role='guest',step=0;return {get role(){return role},get step(){return step},select(value){if(!READ_SYNC_ROLES.includes(value))return false;role=value;step=0;return true;},next(){if(step>=4)return false;step++;return true;},reset(){step=0;},view(){return {role,step,online:step!==1,old:'read',server:step>=3?'read':'waiting',other:step>=4?'read':'unread',queued:step===1||step===2};}};}
